fn solve(n: i8) -> (i8, char) {
    // Compute the non-negative remainder of n modulo 4
    let r = n.rem_euclid(4);
    // Based on the problem's specified cases:
    //  r == 1 => (0, 'A')
    //  r == 2 => (1, 'B')
    //  r == 3 => (2, 'A')
    //  r == 0 => (1, 'A')
    match r {
        1 => (0, 'A'),
        2 => (1, 'B'),
        3 => (2, 'A'),
        0 => (1, 'A'),
        _ => unreachable!(),  // We've covered all 0..=3
    }
}

